// Dispatch through Fabric instead of the legacy JS-module event emitter.
private fun dispatchRiveEvent(reactContext: ReactContext, eventName: String, data: WritableMap) {
  UIManagerHelper.getEventDispatcher(reactContext)?.dispatchEvent(
    RiveCallbackEvent(UIManagerHelper.getSurfaceId(this), id, eventName, data)
  )
}

private class RiveCallbackEvent(
  surfaceId: Int,
  viewTag: Int,
  private val callbackName: String,
  private val payload: WritableMap
) : Event<RiveCallbackEvent>(surfaceId, viewTag) {
  override fun getEventName(): String = callbackName
  override fun getEventData(): WritableMap = payload
  // Every animation/state/error callback matters, including consecutive same-name events.
  override fun canCoalesce(): Boolean = false
}

